<?php require_once __DIR__ . '/includes/config.php';auth();$p=db();$stats=['Employees'=>$p->query('SELECT COUNT(*) FROM employees')->fetchColumn(),'Active employees'=>$p->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn(),'Payroll entries'=>$p->query('SELECT COUNT(*) FROM payroll')->fetchColumn(),'Open flags'=>$p->query("SELECT COUNT(*) FROM investigations WHERE status IN ('pending','under_review')")->fetchColumn()];head('Dashboard');?><h1>Dashboard</h1><div class="cards"><?php foreach($stats as $k=>$v):?><article><small><?=e($k)?></small><strong><?=$v?></strong></article><?php endforeach;?></div><section class="panel"><h2>Payroll verification</h2><p>The detection tool checks payroll employee numbers against the employee register and flags payments linked to inactive, terminated or retired employees.</p><a class="button" href="detect.php">Run ghost-worker detection</a><?php if($_SESSION['user']['role']==='admin'):?> <a class="button" href="change_password.php">Change Administrator Password</a><?php endif;?></section><?php foot();?>